/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
export type Maybe<T> = T | null;
export type InputMaybe<T> = Maybe<T>;
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  /** ISO8601 Date values */
  Directus_Date: { input: unknown; output: unknown; }
  /** BigInt value */
  Directus_GraphQLBigInt: { input: unknown; output: unknown; }
  /** A JSON filter value: a plain object mapping JSON path keys to filter operators (e.g. { "key": { "_eq": "value" } }) */
  Directus_GraphQLJsonFilter: { input: unknown; output: unknown; }
  /** A Float or a String */
  Directus_GraphQLStringOrFloat: { input: unknown; output: unknown; }
  /** Hashed string values */
  Directus_Hash: { input: unknown; output: unknown; }
  /** The `JSON` scalar type represents JSON values as specified by [ECMA-404](http://www.ecma-international.org/publications/files/ECMA-ST/ECMA-404.pdf). */
  Directus_JSON: { input: unknown; output: unknown; }
  Directus_TransportOptions: { input: unknown; output: unknown; }
  _DirectiveExtensions: { input: unknown; output: unknown; }
  join__FieldSet: { input: unknown; output: unknown; }
  link__Import: { input: unknown; output: unknown; }
};

export enum Directus_EventEnum {
  Create = 'create',
  Delete = 'delete',
  Update = 'update'
}

